import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
ORIGINS=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]
def T(xyz=[0,0,0],rot=np.eye(3)):
 t=np.eye(4);t[:3,3]=xyz;t[:3,:3]=rot;return t
def fk(q):
 t=T([0,-.4,.78],R.from_euler('z',np.pi/2).as_matrix())
 for a,(p,rx) in zip(q,ORIGINS):
  t=t@T(p,R.from_euler('x',rx).as_matrix())@T(rot=R.from_euler('z',a).as_matrix())
 return t@T([0,0,.107],R.from_euler('z',-np.pi/4).as_matrix())
def ik(xyz,rot,q):
 lim=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
 def err(v):
  t=fk(v);return np.r_[10*(t[:3,3]-xyz),R.from_matrix(rot@t[:3,:3].T).as_rotvec(),.01*(v-q)]
 s=least_squares(err,q,bounds=(lim[:,0],lim[:,1]),xtol=1e-12,ftol=1e-12,gtol=1e-12)
 if np.linalg.norm(fk(s.x)[:3,3]-xyz)>.003: raise ValueError((s.x,err(s.x)))
 return s.x
if __name__=='__main__':
 import json
 m=json.load(open('/app/output/initial/meta.json'));p=m['proprio']['now'];t=fk(p[:7]);print(t);print('actual',p[16:]);print('quat',R.from_matrix(t[:3,:3]).as_quat(scalar_first=True))
 spec=json.load(open('/app/output/spec.json'));c=spec['cameras']['forward'];d=np.load('/app/output/initial/depth_forward.npy')[-1];k=np.array(c['intrinsic_cv']);pose=np.array(c['cam2world_gl'])
 for u,v in [(99,154),(116,154),(134,154),(151,154),(169,154),(186,154),(204,154),(215,232)]:
  dep=float(d[v,u]);pt=pose@np.r_[(u-160)*dep/k[0,0],-(v-160)*dep/k[1,1],-dep,1];print(u,v,dep,pt[:3])
